import test from "node:test";
import assert from "node:assert/strict";
import { decodeChunks } from "./chunks.mjs";

test("exhaustive two-chunk split preserves string", () => {
  const buf = Buffer.from("héllo 🌍 wörld", "utf8");
  for (let i = 1; i < buf.length; i++) {
    const a = buf.subarray(0, i);
    const b = buf.subarray(i);
    assert.equal(decodeChunks([a, b]), "héllo 🌍 wörld", `split at offset ${i}`);
  }
});

