import test from "node:test";
import assert from "node:assert/strict";
import { decodeChunks } from "./chunks.mjs";

const STR = "héllo 🌍 wörld";

test("exhaustive two-chunk split preserves string", () => {
  const buf = Buffer.from(STR, "utf8");
  const bad = [];
  for (let i = 1; i < buf.length; i++) {
    if (decodeChunks([buf.subarray(0, i), buf.subarray(i)]) !== STR) {
      bad.push(i);
    }
  }
  assert.deepEqual(bad, [], `corrupt splits at offsets: ${bad.join(", ")}`);
});

test("three-chunk split with both boundaries inside the emoji's 4 bytes", () => {
  const buf = Buffer.from(STR, "utf8");
  // emoji starts at byte 7 ('héllo ' = 7 bytes), spans bytes 8..11
  assert.equal(buf[7], 0xf0); // start of 4-byte sequence
  const a = buf.subarray(0, 9);
  const b = buf.subarray(9, 11);
  const c = buf.subarray(11);
  assert.equal(decodeChunks([a, b, c]), STR);
});

