import { StringDecoder } from "node:string_decoder";

export function decodeChunks(buffers) {
  // buffers: array of Buffer chunks from a network stream
  const decoder = new StringDecoder("utf8");
  let out = "";
  for (const b of buffers) out += decoder.write(b);
  out += decoder.end();
  return out;
}

